use core.process as process

fn usage() Never -> {                      // valid: the return slot
    print("usage: tool <count>")
    process.exit(2)
}

fn count(arg: String) Int -> {
    return Int.parse(arg) ?? usage()
}

fn run_then_stop(stop: fn() Never) Never -> stop()   // valid: return slot of a function type

fn almost(flag: Bool) Never -> {
    if flag -> { panic("stop") }
}
// error: `almost` promises to never return, but one path returns
//   Why: `Never` means every path ends in panic, exit, or a call that never returns
