// Illustrative graph. Lines marked proposed are not shipped API.
// #Target(Web) selects web. fn run() App returns the program. WebPage is an HTML page. route maps a URL to a page.
// An effect row after -[...] names work the function needs.
// DB.Read loads public data. Browser runs only in the browser.
// RequestContext.Read covers any session, cookie, auth, or per-request header read.
use core.web as web
#Target(Web)

fn home() WebPage -> web.page("Shop", "featured products")
fn load_list() String -[DB.Read]> { return "products from database" }
fn list() WebPage -> web.page("Products", "rows from loader")
fn save_detail() { print("saved") }
fn detail() WebPage -> web.page("Product", "editable form")
fn settings() WebPage -[Browser]> { return web.page("Settings", "account controls") }
fn load_account() String -[RequestContext.Read]> { return "private account data" }
fn account() WebPage -[RequestContext.Read]> {
    let user = core.auth.current_user()
    return web.page("Account", "Hi, {user.name}")
}
fn save_account() { print("updated") }

fn run() App -> {
    return web.app()
        .route("/", home)
        // proposed: loader(path, fn) attaches a typed loader to one route.
        .loader("/list", load_list)
        .route("/list", list)
        // proposed: form paths use literal route URLs in this ballot.
        .form("/detail", save_detail)
        .route("/detail", detail)
        .route("/settings", settings)
        .loader("/account", load_account)
        .route("/account", account)
        .form("/account", save_account)
        // proposed: cache(path, policy) writes one cache fact per route.
        .cache("/", "immutable")
        .cache("/list", "revalidate")
        .cache("/detail", "private")
        .cache("/settings", "private")
        .cache("/account", "private")
        .hydration_release()
}

// Mode law: no runtime data=static; loader DB.Read=server+stream; interaction nests island; Browser-only page=client.
// RequestContext.Read always blocks static output and shared caching.
// Request: GET /list. Response: shell, then rows. Request: POST /detail. Response: saved.
// Request: GET /account with Mira's session. Response: Hi, Mira. Another user receives that user's own output.
// `jet explain --web-graph` shows:
// / [static] reason=no runtime data cache=immutable
// /list [server+stream] reason=loader DB.Read cache=revalidate
// /detail [server+island] reason=form interaction cache=private
// /settings [client] reason=Browser effect cache=private
// /account [server+island] reason=RequestContext.Read+form cache=private static=no
// Before an internal edit: /list [static]. After list calls proposed core.db.products(): /list [server+stream] reason=transitive DB.Read.
// Proposed capture test: the detail island captures DatabaseHandle db, which cannot be serialized.
// First request: setup_count=1. Resume click: setup_count=1 and click_count=1.
// Diagnostic: E_WEB_SERIALIZE_CAPTURE: /detail captures non-serializable DatabaseHandle db; pass an id or use client rendering.
// Browser gets the /list shell, then rows. A crawler gets complete HTML before response end.
// A mode change invalidates the old route artifact before redeploy.

