use core.web as web
#Target(Web)

fn home() WebPage -> web.page("Shop", "featured products")
fn load_list() String -[DB.Read]> { return "products from database" }
fn list() WebPage -> web.page("Products", "rows from loader")
fn save_detail() { print("saved") }
fn detail() WebPage -> web.page("Product", "editable form")
fn settings() WebPage -[Browser]> { return web.page("Settings", "account controls") }
fn load_account() String -[RequestContext.Read]> { return "private account data" }
fn account() WebPage -[RequestContext.Read]> {
    let user = core.auth.current_user()
    return web.page("Account", "Hi, {user.name}")
}
fn save_account() { print("updated") }

fn run() App -> {
    return web.app()
        .route("/", home)
        // proposed: route-local loader supplies its effect row.
        .loader("/list", load_list)
        .route("/list", list)
        // proposed: route-local form supplies interaction.
        .form("/detail", save_detail)
        .route("/detail", detail)
        .route("/settings", settings)
        .loader("/account", load_account)
        .route("/account", account)
        .form("/account", save_account)
        // proposed: route-local cache facts are checked against derived facts.
        .cache("/", "immutable")
        .cache("/list", "revalidate")
        .cache("/detail", "private")
        .cache("/settings", "private")
        .cache("/account", "private")
        .hydration_release()
}

// Derived graph:
// / [static] reason=no runtime data cache=immutable
// /list [server+stream] reason=loader DB.Read cache=revalidate
// /detail [server+island] reason=form interaction cache=private
// /settings [client] reason=Browser effect cache=private
// /account [server+island] reason=RequestContext.Read+form cache=private static=no
// Page and loader effects are both inputs. An internal DB.Read call changes /list from [static] to [server+stream].
// /detail island: its setup runs once on the first request; a resumed click runs no setup again (the card adds counters to prove it).
// Browser gets the /list shell, then rows, in one response sent in page order.
// A reader that waits for the response to finish, such as a search crawler, gets the complete page; nothing identifies crawlers.
// Proposed expert exit: .route("/settings", settings).render("csr") records override=csr in the graph.
// Proposed conflict: .route("/list", list).render("static") emits E_WEB_RENDER_CONFLICT because DB.Read needs runtime data.
// Proposed project exit: rendering = "explicit" requires route labels instead of derivation.
// A mode change purges the old route cache artifact before deploy.
// /account: RequestContext.Read alone (cookies, session, auth) derives server with private cache; never static.
// Edit: home() starts calling core.db.featured(). jet dev prints: /: static → server+stream (home → core.db.featured reads DB.Read)
// package.jet (proposed):
//   web: .{ hosting: .Static }
// With that pin the same edit is E_WEB_HOSTING_PIN: / needs server hosting: home → core.db.featured reads DB.Read; the project pins .Static
// Without a pin, `jet build --release` refuses the static-to-server change against the last release receipt until a pin is written.

// A separate program: an island whose setup captures a value that cannot cross to the browser.
