// Browser state: the note, scroll, and focus belong to the page.
// Server state: the counter and open connection belong to the server.
// #Target(Web) connects the page and server.
// #Persist asks Jet to carry server_count across restart.
// Signal<Int> is the browser counter's number type.
// #Reactive reruns browser output when the signal changes.
// A game world or command-line input can also be marked #Persist.

use core.web as web
use core.reactive as reactive
#Target(Web)

#Persist server_count := 0

fn make_client_count() Signal<Int> -> reactive.signal(0)

fn home() WebPage -> web.page(
    "Feedback",
    "<form id='feedback'><input name='note'><button>Send</button></form><output id='count'>{server_count}</output>"
)

fn submit() {
    server_count += 1
    print("accepted {server_count}")
}

fn run() App -> {
    client_count :: make_client_count()
    #Reactive {
        print("client count {client_count.get()}")
    }
    return web.app()
        .csr()
        .route("/", home)
        .form("feedback", submit)
        .mount("/api", submit, "Net", "csrf")
        .hydration_dev()
}

