### server.ts — complete in-the-wild server adaptation

```typescript
import "reflect-metadata";
import { Controller, Module } from "@nestjs/common";
import { NestFactory } from "@nestjs/core";
import { Ctx, EventPattern, KafkaContext, Payload, Transport } from "@nestjs/microservices";
import type { MicroserviceOptions } from "@nestjs/microservices";
import { recordOrderOnce } from "./orders.js";
import type { Order } from "./orders.js";

@Controller()
class OrdersConsumer {
  @EventPattern("orders.created")
  async record(@Payload() order: Order, @Ctx() context: KafkaContext) {
    await recordOrderOnce(order);
    if (process.env.HOLD_AFTER_RECORD === "1") await new Promise<void>(() => {});
    const next = (BigInt(context.getMessage().offset) + 1n).toString();
    await context.getConsumer().commitOffsets([{
      topic: context.getTopic(), partition: context.getPartition(), offset: next
    }]);
  }
}
@Module({ controllers: [OrdersConsumer] })
class AppModule {}
const app = await NestFactory.createMicroservice<MicroserviceOptions>(AppModule, {
  transport: Transport.KAFKA,
  options: {
    client: { clientId: "orders-consumer", brokers: ["127.0.0.1:9092"] },
    consumer: { groupId: "order-fixture" }, postfixId: "",
    subscribe: { fromBeginning: true }, run: { autoCommit: false }
  }
});
app.enableShutdownHooks();
await app.listen();
```


