use invoice as work
fn run() {
    queue :: jobs.queue() ?? panic("queue open failed")
    receipt :: queue.enqueue(work.Invoice, "order-41", key: "invoice-41")
        ?? panic("enqueue failed")
    _ :: queue.receipt(receipt.id) ?? panic("receipt read failed")
}
```

