// Store code: the index file was read fine, but one row is broken.
fn refuse_row(path: String) -> IOError Never! {
    IOError.InvalidData(IOContext{operation: .Read, resource: Val(path),
        os_code: None, cause: Val("malformed store entry")})
}

// Caller code: pick the repair from the kind alone.
error :: refuse_row("index")
print(error)    // invalid data during read `index`: malformed store entry
if error == {
    .InvalidData(_) -> print("repair the stored index")
    .InvalidInput(_) -> print("fix the arguments you passed")
    else -> print("other failure: {error}")
}
// prints: repair the stored index

